import jax
import jax.numpy as jnp

def solve(initial, target, rate, tolerance, limit):
    def body(_, carry):
        state, steps = carry
        stopped = ((steps >= limit) | (steps >= 16)
                   | (jnp.abs(target - state) <= tolerance))
        return jax.lax.cond(
            stopped,
            lambda _: carry,
            lambda _: (state + rate * (target - state), steps + 1),
            operand=None,
        )

    # A static bound supports reverse mode; the conditional freezes the carry
    # as soon as a runtime stopping condition holds.
    return jax.lax.fori_loop(0, 16, body, (initial, jnp.int32(0)))

