import jax.numpy as jnp

def solve(initial, target, rate, tolerance, limit):
    def body(_, carry):
        state, steps = carry
        active = (steps < limit) & (jnp.abs(target-state) > tolerance)

        def update(carry):
            state, steps = carry
            return state + rate * (target-state), steps + 1

